<div class="border-t border-outline-variant bg-white px-4 py-3 sm:px-5">
    <div x-show="pickerOpen" x-cloak class="mb-3 rounded-2xl border border-neutral-200 bg-white p-3 shadow-lg"><p class="mb-2 text-xs font-semibold text-neutral-500">Emoji</p><div class="grid grid-cols-8 gap-1 text-xl"><template x-for="emoji in emojis"><button type="button" @click="insertEmoji(emoji)" class="rounded-lg p-1 hover:bg-neutral-100" x-text="emoji"></button></template></div><p class="mb-2 mt-3 text-xs font-semibold text-neutral-500">Stickers</p><div class="flex gap-3 text-3xl"><template x-for="sticker in stickers"><button type="button" @click="sendSticker(sticker.key)" class="rounded-xl p-1 hover:bg-neutral-100" x-text="sticker.emoji"></button></template></div></div>
    <form @submit.prevent="sendMessage" class="flex items-center gap-1 rounded-[22px] border border-neutral-300 px-3 py-1.5"><button type="button" @click="pickerOpen = !pickerOpen" class="flex h-8 w-8 items-center justify-center rounded-full hover:bg-neutral-100" aria-label="Emoji picker"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M8 14s1.5 2 4 2 4-2 4-2M9 9h.01M15 9h.01"/></svg></button><button type="button" @click="pickerOpen = true" class="flex h-8 w-8 items-center justify-center rounded-full text-xs font-bold hover:bg-neutral-100" aria-label="Sticker picker">GIF</button><input x-ref="messageInput" x-model="newMessage" type="text" maxlength="5000" placeholder="Message..." :disabled="sending" class="min-w-0 flex-1 border-0 bg-transparent px-1 py-2 text-sm outline-none focus:ring-0"/><button type="submit" :disabled="!newMessage.trim() || sending" class="pr-1 text-sm font-semibold text-[#0095f6] disabled:opacity-40">Send</button></form>
</div>
